//! The bundled datasets, compiled into the wasm so every tool works offline.
//!
//! `asteroids.json` is generated by `scripts/fetch-asteroids.mjs` from JPL's
//! NHATS and SBDB APIs. Delta v and round trip duration are real trajectory
//! results, not estimates. Composition carries its own source field.

use serde::{Deserialize, Serialize};

pub const ASTEROIDS_JSON: &str = include_str!("../../data/asteroids.json");
pub const SHIPS_JSON: &str = include_str!("../../data/ships.json");
pub const ASSUMPTIONS_JSON: &str = include_str!("../../data/assumptions.json");

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Composition {
    pub water: f64,
    pub iron: f64,
    pub nickel: f64,
    pub cobalt: f64,
    pub pgm_ppm: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Asteroid {
    pub id: String,
    pub des: String,
    #[serde(default)]
    pub fullname: String,
    pub delta_v_km_s: f64,
    pub round_trip_days: f64,
    pub diameter_m: Option<f64>,
    pub diameter_source: String,
    pub composition: Composition,
    pub composition_class: String,
    pub composition_source: String,
    #[serde(default)]
    pub albedo: Option<f64>,
    #[serde(default)]
    pub density_g_cm3: Option<f64>,
    #[serde(default)]
    pub rotation_period_h: Option<f64>,
    #[serde(default)]
    pub spectral_class: Option<String>,
    #[serde(default)]
    pub h_mag: Option<f64>,
    #[serde(default)]
    pub orbit_condition_code: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct AsteroidDoc {
    asteroids: Vec<Asteroid>,
}

/// A ship in the catalogue.
///
/// The numbers that a real spacecraft's operator has not published are
/// `Option` and arrive as `None`. That is deliberate: a mission cannot be
/// planned for a ship whose propellant load is secret, and the honest answer is
/// to say which figures are missing rather than to invent them. `specs(&self)`
/// is the only way to reach them, and it reports what is absent.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Ship {
    pub id: String,
    pub name: String,
    pub class: String,
    pub dry_mass_tons: f64,
    pub propellant_capacity_tons: Option<f64>,
    pub cargo_capacity_tons: Option<f64>,
    pub exhaust_velocity_m_s: Option<f64>,
    pub extraction_rate_kg_s: Option<f64>,
    pub capital_cost_usd: Option<f64>,
    pub design_life_missions: f64,
    pub transfer_time_multiplier: f64,
    pub notes: String,

    /// flown, in_development or speculative. See ships.json.
    #[serde(default)]
    pub tier: String,
    #[serde(default)]
    pub operator: String,
    #[serde(default)]
    pub status: String,
    /// Which 3D silhouette the simulator draws for this ship.
    #[serde(default)]
    pub model: String,
    #[serde(default)]
    pub isp_s: Option<f64>,
    #[serde(default)]
    pub sample_returned_kg: Option<f64>,
    /// Field name to citation, so any figure on screen can be traced.
    #[serde(default)]
    pub sources: serde_json::Value,
    #[serde(default)]
    pub uncertainty: String,
    /// Speculative ships only: which real thruster the performance comes from.
    #[serde(default)]
    pub basis: String,
}

/// Every published figure a mission needs, or the list of what is missing.
pub struct ShipSpecs {
    pub propellant_capacity_tons: f64,
    pub cargo_capacity_tons: f64,
    pub exhaust_velocity_m_s: f64,
    pub extraction_rate_kg_s: f64,
}

impl Ship {
    /// Returns the specs, or the names of the fields this ship does not publish.
    pub fn specs(&self) -> Result<ShipSpecs, Vec<&'static str>> {
        let mut missing = Vec::new();
        if self.propellant_capacity_tons.is_none() {
            missing.push("propellant_capacity_tons");
        }
        if self.cargo_capacity_tons.is_none() {
            missing.push("cargo_capacity_tons");
        }
        if self.exhaust_velocity_m_s.is_none() {
            missing.push("exhaust_velocity_m_s");
        }
        if self.extraction_rate_kg_s.is_none() {
            missing.push("extraction_rate_kg_s");
        }
        if !missing.is_empty() {
            return Err(missing);
        }
        Ok(ShipSpecs {
            propellant_capacity_tons: self.propellant_capacity_tons.unwrap(),
            cargo_capacity_tons: self.cargo_capacity_tons.unwrap(),
            exhaust_velocity_m_s: self.exhaust_velocity_m_s.unwrap(),
            extraction_rate_kg_s: self.extraction_rate_kg_s.unwrap(),
        })
    }

    /// A real spacecraft that flew, as opposed to one of the invented haulers.
    pub fn is_real(&self) -> bool {
        self.tier == "flown" || self.tier == "in_development"
    }
}

#[derive(Debug, Clone, Deserialize)]
struct ShipDoc {
    ships: Vec<Ship>,
}

/// The constants the cost and revenue model needs, flattened out of
/// `assumptions.json` so the economics code is not full of string lookups.
#[derive(Debug, Clone, Copy)]
pub struct Assumptions {
    pub water_usd_per_ton: f64,
    pub iron_usd_per_ton: f64,
    pub nickel_usd_per_ton: f64,
    pub cobalt_usd_per_ton: f64,
    pub pgm_usd_per_ton: f64,
    pub propellant_usd_per_ton: f64,
    pub operations_usd_per_day: f64,
    pub delta_v_split: f64,
    pub included_stay_days: f64,
    pub ore_density_t_per_m3: f64,
}

fn num(v: &serde_json::Value, path: &[&str]) -> f64 {
    let mut cur = v;
    for key in path {
        cur = &cur[*key];
    }
    cur.as_f64().unwrap_or_else(|| {
        panic!("assumptions.json is missing a numeric value at {path:?}");
    })
}

pub fn asteroids() -> Vec<Asteroid> {
    let doc: AsteroidDoc =
        serde_json::from_str(ASTEROIDS_JSON).expect("asteroids.json is not valid");
    doc.asteroids
}

pub fn ships() -> Vec<Ship> {
    let doc: ShipDoc = serde_json::from_str(SHIPS_JSON).expect("ships.json is not valid");
    doc.ships
}

pub fn assumptions() -> Assumptions {
    let v: serde_json::Value =
        serde_json::from_str(ASSUMPTIONS_JSON).expect("assumptions.json is not valid");
    Assumptions {
        water_usd_per_ton: num(&v, &["commodity_prices_usd_per_ton", "water_in_orbit", "value"]),
        iron_usd_per_ton: num(&v, &["commodity_prices_usd_per_ton", "iron", "value"]),
        nickel_usd_per_ton: num(&v, &["commodity_prices_usd_per_ton", "nickel", "value"]),
        cobalt_usd_per_ton: num(&v, &["commodity_prices_usd_per_ton", "cobalt", "value"]),
        pgm_usd_per_ton: num(
            &v,
            &["commodity_prices_usd_per_ton", "platinum_group_metals", "value"],
        ),
        propellant_usd_per_ton: num(&v, &["cost_model", "propellant_usd_per_ton", "value"]),
        operations_usd_per_day: num(&v, &["cost_model", "operations_usd_per_day", "value"]),
        delta_v_split: num(&v, &["mission_model", "delta_v_split", "value"]),
        included_stay_days: num(&v, &["mission_model", "included_stay_days", "value"]),
        ore_density_t_per_m3: num(&v, &["mission_model", "ore_density_t_per_m3", "value"]),
    }
}

/// Accepts the generated id, the JPL designation, or the full name, because the
/// model will try all three.
pub fn find_asteroid(list: &[Asteroid], needle: &str) -> Option<Asteroid> {
    let n = needle.trim().to_lowercase();
    list.iter()
        .find(|a| {
            a.id.to_lowercase() == n
                || a.des.to_lowercase() == n
                || a.fullname.to_lowercase() == n
                || a.des.to_lowercase().replace(' ', "-") == n
        })
        .or_else(|| list.iter().find(|a| a.fullname.to_lowercase().contains(&n)))
        .cloned()
}

pub fn find_ship(list: &[Ship], needle: &str) -> Option<Ship> {
    let n = needle.trim().to_lowercase();
    list.iter()
        .find(|s| s.id.to_lowercase() == n || s.name.to_lowercase() == n)
        .cloned()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_datasets_parse() {
        let a = asteroids();
        let s = ships();
        assert!(a.len() >= 40, "only {} asteroids bundled", a.len());
        assert_eq!(s.len(), 7, "four real spacecraft and three invented haulers");
        let _ = assumptions();
    }

    #[test]
    fn every_asteroid_has_real_delta_v_and_duration() {
        for a in asteroids() {
            assert!(a.delta_v_km_s > 0.0 && a.delta_v_km_s < 20.0, "{} dv {}", a.des, a.delta_v_km_s);
            assert!(a.round_trip_days > 0.0, "{} days {}", a.des, a.round_trip_days);
        }
    }

    #[test]
    fn every_asteroid_declares_where_its_composition_came_from() {
        let allowed = ["spectral_taxonomy", "albedo_inference", "unknown_assumed_stony"];
        for a in asteroids() {
            assert!(
                allowed.contains(&a.composition_source.as_str()),
                "{} has composition_source {}",
                a.des,
                a.composition_source
            );
        }
    }

    #[test]
    fn lookup_accepts_id_designation_and_name() {
        let list = asteroids();
        let bennu = find_asteroid(&list, "101955").expect("Bennu by designation");
        assert_eq!(find_asteroid(&list, &bennu.id).unwrap().des, bennu.des);
        assert!(find_asteroid(&list, "Bennu").is_some(), "Bennu by name");
        assert!(find_asteroid(&list, "not a real object").is_none());
    }

    #[test]
    fn ship_lookup_works_by_id_and_name() {
        let list = ships();
        assert!(find_ship(&list, "ion-freighter").is_some());
        assert!(find_ship(&list, "Ion Freighter").is_some());
        assert!(find_ship(&list, "millennium falcon").is_none());
    }
}
